        item = drafts.get(index)
        if not item:
            return
        if etype == "content_block_delta":
            d = e.get("delta") or {}
            dt = d.get("type")
            if dt == "text_delta" and item.kind == "text":
                item.text += d.get("text") or ""
            elif dt == "thinking_delta" and item.kind == "thinking":
                item.text += d.get("thinking") or ""
