                        parent,
                    )
            elif btype in ("tool_use", "server_tool_use", "mcp_tool_use") and b.get("id"):
                t = self.tools.get(b["id"])
                if not t:
                    t = ToolItem(
                        id=b["id"],
                        name=b.get("name") or btype,
                        input=b.get("input") or {},
                        input_json="",
                        input_done=True,
                        status="running",
                        children=[],
                        start_ts=ts,
                        parent_id=parent,
                    )
