        self.confirm_btn.setAccessibleName(spec.confirm)
        self.confirm_btn.setDefault(True)
        self.confirm_btn.setProperty("autofocus", True)
        self.add_footer(self.cancel_btn, self.confirm_btn)

    def checked(self) -> bool:
