        self.lay = QVBoxLayout(host)
        self.lay.setContentsMargins(6, 6, 6, 6)
        self.lay.setSpacing(0)
        self.setWidget(host)


def _list_area(max_h: int = 300) -> _ListArea:
    return _ListArea(max_h)


class _Foot(QWidget):
    def __init__(self) -> None:
        super().__init__()
        self.setObjectName("fpick-foot")
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        t = theme.tokens()
        self.setStyleSheet(f"#fpick-foot {{ border-top: 1px solid {theme.blend(t.hair, t.raised).name()}; }}")
        self.lay = QHBoxLayout(self)
        self.lay.setContentsMargins(8, 6, 8, 6)
