class Tile(LayoutButton):
    """One figure about the fleet (``.ov-tile``). Clicking it scrolls to the matching section."""

    def __init__(self, icon: str, label: str, on_click: Callable[[], None], parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self._icon = icon
        self._tone = ""
        self._live = False
        self.setCursor(Qt.CursorShape.PointingHandCursor)
        self.setAccessibleName(label)
        self.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Fixed)
        self.clicked.connect(on_click)
        lay = QHBoxLayout(self)
        lay.setContentsMargins(14, 12, 14, 12)
        lay.setSpacing(12)
        self.ico_box = QFrame()
        self.ico_box.setObjectName("tile-ico")
        self.ico_box.setFixedSize(34, 34)
        self.ico_box.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        il = QHBoxLayout(self.ico_box)
        il.setContentsMargins(0, 0, 0, 0)
        self.ico = QLabel()
        self.ico.setAlignment(Qt.AlignmentFlag.AlignCenter)
        il.addWidget(self.ico, 0, Qt.AlignmentFlag.AlignCenter)
        self.mark = WorkingMark(18)
        self.mark.hide()
        il.addWidget(self.mark, 0, Qt.AlignmentFlag.AlignCenter)
        lay.addWidget(self.ico_box)
        col = QVBoxLayout()
        col.setContentsMargins(0, 0, 0, 0)
        col.setSpacing(1)
        self.value = QLabel("0")
        col.addWidget(self.value)
        self.key = ElideLabel(label)
        col.addWidget(self.key)
        lay.addLayout(col, 1)
        bind(theme.theme.changed, self, lambda _t: self._paint())
        self._label = label
        self._sub = ""
        self._paint()

    def set_value(self, text: str, tone: str = "", sub: str = "", live: bool = False) -> None:
        self.value.setText(text)
        self._tone, self._sub, self._live = tone, sub, live
        self._paint()

    def _paint(self) -> None:
        t = theme.tokens()
        accent = self._tone == "accent"
        self.setStyleSheet(
            f"Tile {{ background: {t.raised}; border: 1px solid {theme.blend(t.hair_2, t.canvas).name()}; border-radius: 14px; text-align: left; padding: 0; }} "
            f"Tile:hover {{ border-color: {theme.blend(t.hair_3, t.canvas).name()}; }}"
        )
        box_bg = theme.blend(t.accent_wash, t.raised).name() if accent else theme.blend(t.fill_1, t.raised).name()
        self.ico_box.setStyleSheet(f"#tile-ico {{ background: {box_bg}; border-radius: 10px; }}")
        self.ico.setPixmap(
            icons.pixmap(self._icon, t.accent_text if accent else (t.text if self._live else t.text_2), 16)
        )
        self.ico.setVisible(not self._live)
        self.mark.setVisible(self._live)
        self.value.setStyleSheet(
            f"color: {t.accent_text if accent else t.text}; font-size: {theme.FS_DISPLAY}px; font-weight: 600;"
        )
        self.key.setText(f"{self._label} · {self._sub}" if self._sub else self._label)
        self.key.setStyleSheet(f"color: {t.text_3}; font-size: {theme.FS_MICRO}px;")


