class ErrorBar(QWidget):
    """The line under the header when the session stopped with an error (``.session-error``)."""

    def __init__(self, session_id: str, parent: Optional[QWidget] = None) -> None:
        super().__init__(parent)
        self.sid = session_id
        self._error = ""
        host = QWidget()
