        brand.addWidget(name, 1)
        self.collapse_btn = IconButton("panel-left-close", "Hide sidebar (Ctrl+B)", 15)
        self.collapse_btn.clicked.connect(lambda: store.set_ui(sidebar=False))
        brand.addWidget(self.collapse_btn)
