        )
        self.page_inbox = NavButton("inbox", "Inbox")
        self.page_inbox.setToolTip("Results of scheduled sessions")
        self.page_inbox.clicked.connect(lambda: store.show_page("session" if store.page == "inbox" else "inbox"))
