        self.inner.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Preferred)
        ol.addStretch(1)
        ol.addWidget(self.inner, 100)
        ol.addStretch(1)
        il = QVBoxLayout(self.inner)
        il.setContentsMargins(24, 22, 24, 44)
        il.setSpacing(0)
