    def find_entries(self) -> List[Tuple[int, str, str]]:
        """(unit index, item id, text) for everything the find bar searches, from the models, not the widgets."""
        out: List[Tuple[int, str, str]] = []
        cwd = self.cwd
        for i, u in enumerate(self._units):
