            if any(
                it.id == item_id or getattr(it, "uuid", None) == item_id
                for it in (u.work if isinstance(u, WorkUnit) else u.items)
            ):
                idx = i
                break
        if idx < 0:
            return None
        p = idx // PAGE
        page = self._pages[p] if p < len(self._pages) else None
        if page is None:
