        items = m.items
        self.empty_host.setVisible(loaded and not items and self._empty is not None)
        running = bool(r and r.status in BUSY)
        units = group_turns(items, running)
        self._units = units
        pend: Dict[str, dict] = {}
        for p in r.pending if r else []:
