    return;
  }
  const chrome = shell === 'chrome' ? findChrome() : null;
  if (shell === 'chrome' && !chrome) {
    console.log('No Chrome/Chromium found; opening Pilcrow in your default browser instead.');
    shell = 'browser';
  }
