  const last = steps[steps.length - 1];
  let commit = last?.commit || null;
  let files = [];
  if (!last || last.tree !== tree) {
    const args = ['commit-tree', tree, '-m', `${kind}: ${label || ''}`.slice(0, 200)];
    if (last?.commit) args.push('-p', last.commit);
    const ct = await sg(cwd, args);
