              <ContextRing used={ctxUsed} total={ctxTotal} size={16} />
              {ctxPct >= 0.5 && (
                <span className="tnum">
                  <Num value={ctxPct * 100} format={(v) => `${Math.round(v)}%`} />
                </span>
