            <span className="mono ellipsis" title={session.worktree.path}>
              {tildify(session.worktree.path, info?.home)}
            </span>
          </div>
          <div className="row">
            <button className="btn sm" onClick={() => call('shell.openPath', { path: session.worktree!.path })}>
