    if (w === 'edit') edits++;
    else if (w === 'command') commands++;
    else if (w === 'read') reads++;
    else if (w === 'search') searches++;
    else if (w === 'agent') agents++;
    else if (w === 'mcp') mcp++;
    else other++;
