/* ================================================================ side panel
   Lives on the chrome surface like the sidebar. Tabs are text with a sliding underline;
   each tab has one toolbar row of borderless controls. */

.panel {
  flex: 0 1 auto;
  min-width: 300px;
  /* Never wider than the conversation in a small window, never above 40% of a big one. */
  max-width: max(300px, min(40vw, calc(100vw - 760px)));
  display: flex;
  flex-direction: column;
  background: var(--canvas);
  container-type: inline-size;
}
/* The panel gives way before the conversation does: in a narrow window it shrinks (down to 300px)
   instead of pushing past the window edge. */
.panel-shell {
  flex: 0 1 auto;
  min-width: 0;
  display: flex;
  min-height: 0;
  background: var(--chrome);
}

.panel-tabs {
  position: relative;
  flex: none;
  display: flex;
  align-items: center;
  gap: 2px;
  height: var(--header-h);
  padding: 0 8px 0 10px;
  box-shadow: inset 0 -1px 0 var(--hair);
  overflow-x: auto;
  scrollbar-width: none;
}
.panel-tab {
  position: relative;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  height: 30px;
  padding: 0 8px;
  border-radius: var(--r-2);
  font-size: var(--fs-ui);
  color: var(--text-3);
  white-space: nowrap;
  transition: color var(--t-fast), background var(--t-fast);
}
.panel-tab:hover {
  color: var(--text);
  background: var(--fill-1);
}
.panel-tab.on {
  color: var(--text);
  font-weight: 550;
}
.panel-tab-ico {
  flex: none;
  opacity: 0.85;
}
.panel-tab.on .panel-tab-ico {
  opacity: 1;
}
.panel-ink {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 2px;
  border-radius: 2px 2px 0 0;
  background: var(--text);
  transition: transform var(--t-panel) var(--ease), width var(--t-panel) var(--ease);
  pointer-events: none;
  z-index: 1;
}
.tab-count {
  min-width: 16px;
  height: 16px;
  padding: 0 4px;
  border-radius: 8px;
  background: var(--fill-3);
  color: var(--text);
  font-size: 10.5px;
  font-weight: 600;
  display: grid;
  place-items: center;
}
/* In a narrow panel only the chosen tab keeps its name; the others are icons with tooltips. The name
   grows in and the ink follows, so switching tabs reads as one movement. */
@container (max-width: 759px) {
  .panel-tab:not(.on) .panel-tab-label {
    display: none;
  }
  .panel-tab:not(.on) {
    width: 34px;
    justify-content: center;
    padding: 0;
  }
  .panel-tab.on {
    padding: 0 10px 0 8px;
    animation: tab-name var(--t-panel) var(--ease);
  }
}
@keyframes tab-name {
  from {
    opacity: 0.4;
  }
}

.panel-body {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}
.panel-body > * {
  flex: 1;
  min-height: 0;
}
.panel-keep {
  flex-direction: column;
  min-height: 0;
}
.panel-keep > * {
  flex: 1;
  min-height: 0;
}

.panel-toolbar {
  flex: none;
  display: flex;
  align-items: center;
  gap: 4px;
  min-height: 42px;
  padding: 6px 10px 6px 12px;
  box-shadow: inset 0 -1px 0 var(--hair);
  overflow-x: auto;
  scrollbar-width: none;
  font-size: var(--fs-small);
}
.panel-toolbar .btn.sm {
  height: 26px;
}

.panel .empty {
  padding: 40px 28px;
}

/* ---------------------------------------------------------------- changes */

.changes {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.changes-bar {
  gap: 6px;
}
.changes-scope {
  font-weight: 550;
  color: var(--text);
  white-space: nowrap;
}
.select-btn.ghost-select {
  height: 26px;
  max-width: 200px;
  padding: 0 6px 0 8px;
  background: transparent;
  box-shadow: none;
  font-weight: 550;
}
.select-btn.ghost-select:hover {
  background: var(--fill-2);
}
.changes-stat {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-left: 4px;
  font-size: var(--fs-small);
  white-space: nowrap;
}
.changes-summary {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  font-size: var(--fs-small);
  box-shadow: inset 0 -1px 0 var(--hair);
}
.commit-box {
  flex: none;
  display: grid;
  gap: 8px;
  padding: 12px;
  box-shadow: inset 0 -1px 0 var(--hair);
  animation: rise var(--t-med) var(--ease);
}
.changes-files {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 0 0 24px;
  display: grid;
  align-content: start;
}
/* Files read as one continuous document: sticky headers, hairlines between files, no boxes. */
.cfile {
  min-width: 0;
  box-shadow: inset 0 -1px 0 var(--hair);
}
.cfile-head {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 6px;
  min-height: 40px;
  padding: 0 8px 0 6px;
  background: var(--chrome);
  font-size: var(--fs-small);
}
.cfile.open .cfile-head {
  box-shadow: inset 0 -1px 0 var(--hair);
}
.cfile-head .icon-btn {
  opacity: 0;
  transition: opacity var(--t-fast);
}
.cfile-head:hover .icon-btn,
.cfile-head .icon-btn:focus-visible {
  opacity: 1;
}
.cfile-toggle {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 7px;
  height: 30px;
  padding: 0 4px;
  text-align: left;
  border-radius: var(--r-2);
}
.cfile-toggle > svg {
  flex: none;
  color: var(--text-3);
  transition: transform var(--t-med) var(--ease);
}
.cfile-name {
  font-family: var(--font-mono);
  font-size: 12.5px;
  font-weight: 500;
  white-space: nowrap;
}
.cfile-dir {
  font-family: var(--font-mono);
  font-size: 11.5px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  direction: rtl;
  text-align: left;
}
.fstat {
  flex: none;
  width: 16px;
  height: 16px;
  display: grid;
  place-items: center;
  border-radius: 4px;
  font-family: var(--font-mono);
  font-size: 10px;
  font-weight: 650;
}
.fstat.s-M {
  color: var(--text-2);
  background: var(--fill-2);
}
.fstat.s-A,
.fstat.s-U {
  color: var(--ok);
  background: var(--ok-wash);
}
.fstat.s-D {
  color: var(--err);
  background: var(--err-wash);
}
.fstat.s-R {
  color: var(--info);
  background: var(--info-wash);
}
.cfile-body .diff {
  border-radius: 0;
  max-height: none;
  box-shadow: none;
  background: var(--canvas);
}
.cfile-body .diff-grid {
  padding: 4px 0 8px;
}
.cfile-note {
  padding: 12px 14px;
  font-size: var(--fs-small);
}
.notes-bar {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: var(--raised);
  box-shadow: inset 0 1px 0 var(--hair-2);
  color: var(--text);
  font-size: var(--fs-small);
  animation: rise var(--t-med) var(--ease);
}

/* ---------------------------------------------------------------- files */

.files {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.files-body {
  flex: 1;
  min-height: 0;
  display: flex;
}
.tree {
  width: 212px;
  flex: none;
  overflow: auto;
  padding: 6px 6px 18px;
  box-shadow: inset -1px 0 0 var(--hair);
  font-size: 12.5px;
}
.tree-row {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  height: 26px;
  padding-right: 6px;
  border-radius: var(--r-2);
  text-align: left;
  color: var(--text-2);
  white-space: nowrap;
  transition: background var(--t-fast), color var(--t-fast);
}
.tree-row:hover {
  background: var(--fill-1);
  color: var(--text);
}
.tree-row.on {
