}
.ftab-x {
  display: grid;
  place-items: center;
  width: 20px;
  height: 20px;
  margin-right: 5px;
  border-radius: 4px;
  color: var(--text-3);
  opacity: 0;
  transition: opacity var(--t-fast), background var(--t-fast);
}
.ftab:hover .ftab-x,
