}
.img-preview {
  flex: 1;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 10px;
  padding: 24px;
  overflow: auto;
}
.img-preview img {
  max-width: 100%;
  max-height: 70vh;
  border-radius: var(--r-2);
  box-shadow: var(--shadow-card);
  background: repeating-conic-gradient(var(--fill-2) 0 25%, transparent 0 50%) 0 0 / 16px 16px;
}

/* ---------------------------------------------------------------- terminal */

.terms {
  display: flex;
  flex-direction: column;
  min-height: 0;
}
.ttab {
  display: inline-flex;
  align-items: center;
  flex: none;
  border-radius: var(--r-2);
  font-size: 12px;
  color: var(--text-3);
  transition: color var(--t-fast), background var(--t-fast);
}
.ttab:hover {
  color: var(--text);
}
.ttab button:first-child {
  height: 26px;
  padding: 0 4px 0 9px;
  font-family: var(--font-mono);
}
.ttab.on {
  background: var(--fill-2);
  color: var(--text);
}
.ttab.exited {
